#!/usr/bin/env python3 """Claude 3x10 basic-coding battery runner for SpiritOS Source Proxy.
One-shot diagnostic. Posts messy/vague human prompts to the REAL integrated hot path (/v1/decisions/prompt-packet), retrieves the durable FIP-0 receipt and FIP-6 trace by run id, and classifies each row under a STRICT honesty contract.
Honesty controls (deliberate): - Never sends expected_result_state (would fake the synthetic browser pass). - Never sends trial_recover_already_satisfied (would route to hardcoded no-op). - Pre-seeds each disposable target file so the row exercises FIP-4 replace_file instead of the target_missing gate. Targets live ONLY under the disposable evidence directory.
This runner does not commit, push, stage, or apply. The proxy itself never applies the proposed diff. Targets are disposable evidence fixtures. """ from __future__ import annotations
import argparse import json import ssl import sys import time import urllib.request from datetime import datetime, timezone from pathlib import Path
BASE_URL = "https://127.0.0.1:8787" ROOT = Path("/home/source/SpiritOS") EVID = ROOT / "docs/evidence/source-proxy-claude-3x10-audit-20260615" TARGETS = EVID / "targets" RECEIPTS = EVID / "receipts" TRACES = EVID / "traces" ALLOWED_ROOT_REL = "docs/evidence/source-proxy-claude-3x10-audit-20260615/targets/"
FORBIDDEN_FILES = [ ".env", ".env.local", "certificates", "source_proxy/data", "backend/volumes", "backend/searxng_data", ".spirit-backups", "src/app", "src/components", "src/lib", "package.json", "scripts/media", ]
HARDCODED_REASON_CODES = { "coder_no_changes_needed", "deterministic_agent_trials_ui_test_preview", } HARDCODED_MARKERS = ( "realistic-reversible-live-trial", "deterministic-preview", "agent-trials-ui-test-deterministic-preview", "dummy-coder-001-create-mode", "PASS_DUMMY_PROJECT_INIT", )
PLACEHOLDER = { "js": "// placeholder for claude 3x10 battery; coder must replace this file\n", "ts": "// placeholder for claude 3x10 battery; coder must replace this file\n", "html": "<!-- placeholder for claude 3x10 battery; coder must replace this file -->\n", }
def matrix() -> list[dict]: rows = [ # set, id, raw prompt, category, target rel-path, ext, browser_relevant, expected_score (1, "s1-01-homepage", "init a repo and make a homepage for my app", "scaffold/home", "set1/s1-01-homepage/index.html", "html", True, "verifier_blocked"), (1, "s1-02-calculator", "make calculator app", "calc/logic", "set1/s1-02-calculator/calculator.js", "js", False, "productive_go"), (1, "s1-03-weather", "make weather app", "data/ui", "set1/s1-03-weather/weather.js", "js", False, "productive_go"), (1, "s1-04-todo", "make a todo list thing", "state/crud", "set1/s1-04-todo/todo.js", "js", False, "productive_go"), (1, "s1-05-timer", "make a little timer", "timer", "set1/s1-05-timer/timer.js", "js", False, "productive_go"), (1, "s1-06-notes", "make a notes app", "crud", "set1/s1-06-notes/notes.js", "js", False, "productive_go"), (1, "s1-07-expense", "make a expense splitter", "calc", "set1/s1-07-expense/split.js", "js", False, "productive_go"), (1, "s1-08-chart", "make a simple chart page", "ui", "set1/s1-08-chart/chart.html", "html", True, "verifier_blocked"), (1, "s1-09-signup", "make a signup landing page", "ui", "set1/s1-09-signup/signup.html", "html", True, "verifier_blocked"), (1, "s1-10-status", "make a tiny api route that returns status", "api", "set1/s1-10-status/status.ts", "ts", False, "productive_go"), (2, "s2-01-dashboard", "lets start a repo and make a dashboard for my app", "scaffold/home", "set2/s2-01-dashboard/dashboard.html", "html", True, "verifier_blocked"), (2, "s2-02-counter", "make a time counter app", "timer", "set2/s2-02-counter/counter.js", "js", False, "productive_go"), (2, "s2-03-moon", "make a moon phase app", "data/ui", "set2/s2-03-moon/moon.js", "js", False, "productive_go"), (2, "s2-04-checklist", "make checklist thing i can add and clear", "state/crud", "set2/s2-04-checklist/checklist.js", "js", False, "productive_go"), (2, "s2-05-stopwatch", "make stopwatch card with start pause reset", "timer", "set2/s2-05-stopwatch/stopwatch.js", "js", False, "productive_go"), (2, "s2-06-sticky", "make a quick sticky notes board", "crud", "set2/s2-06-sticky/sticky.js", "js", False, "productive_go"), (2, "s2-07-tip", "make a tip calculator", "calc", "set2/s2-07-tip/tip.js", "js", False, "productive_go"), (2, "s2-08-stats", "make a small stats widget", "data/ui", "set2/s2-08-stats/stats.js", "js", False, "productive_go"), (2, "s2-09-waitlist", "make a product waitlist page", "ui", "set2/s2-09-waitlist/waitlist.html", "html", True, "verifier_blocked"), (2, "s2-10-health", "make a health check endpoint", "api", "set2/s2-10-health/health.ts", "ts", False, "productive_go"), (3, "s3-01-shell", "spin up a tiny app shell with a home screen", "scaffold/home", "set3/s3-01-shell/shell.html", "html", True, "verifier_blocked"), (3, "s3-02-cruncher", "build a basic number cruncher", "calc/logic", "set3/s3-02-cruncher/cruncher.js", "js", False, "productive_go"), (3, "s3-03-forecast", "make a simple forecast-ish demo with fake data if needed", "data/ui", "set3/s3-03-forecast/forecast.js", "js", False, "productive_go"), (3, "s3-04-tasks", "make a task tracker", "state/crud", "set3/s3-04-tasks/tasks.js", "js", False, "productive_go"), (3, "s3-05-countdown", "make a countdown thing", "timer", "set3/s3-05-countdown/countdown.js", "js", False, "productive_go"), (3, "s3-06-journal", "make a mini journal page", "crud", "set3/s3-06-journal/journal.js", "js", False, "productive_go"), (3, "s3-07-budget", "make a budget split helper", "calc", "set3/s3-07-budget/budget.js", "js", False, "productive_go"), (3, "s3-08-progress", "make a simple progress graph", "ui", "set3/s3-08-progress/progress.html", "html", True, "verifier_blocked"), (3, "s3-09-coming-soon", "make a coming soon page", "ui", "set3/s3-09-coming-soon/coming-soon.html", "html", True, "verifier_blocked"), (3, "s3-10-alive", "make an endpoint that says the service is alive", "api", "set3/s3-10-alive/alive.ts", "ts", False, "productive_go"), ] out = [] for set_id, pid, raw, cat, rel, ext, browser, expected in rows: target_rel = f"{ALLOWED_ROOT_REL}{rel}" out.append( { "set_id": set_id, "prompt_id": pid, "raw_prompt": raw, "category": cat, "target": target_rel, "ext": ext, "allowed_target_root": ALLOWED_ROOT_REL, "expected_browser_relevant": browser, "expected_research_need": False, "expected_repair_range": [0, 2], "expected_score_class": expected, "forbidden_paths": FORBIDDEN_FILES, } ) return out
def log(msg: str) -> None: line = f"[{datetime.now(timezone.utc).strftime('%H:%M:%S')}] {msg}" print(line, flush=True) with (EVID / "battery-console.log").open("a", encoding="utf-8") as fh: fh.write(line + "\n")
def request_json(method: str, path: str, body: dict | None = None, timeout: int = 1500): data = json.dumps(body).encode("utf-8") if body is not None else None headers = {"content-type": "application/json"} if data else {} req = urllib.request.Request(f"{BASE_URL}{path}", data=data, headers=headers, method=method) ctx = ssl._create_unverified_context() with urllib.request.urlopen(req, context=ctx, timeout=timeout) as resp: return resp.status, json.loads(resp.read().decode("utf-8"))
def ensure_target(row: dict) -> None: p = ROOT / row["target"] p.parent.mkdir(parents=True, exist_ok=True) if not p.exists(): p.write_text(PLACEHOLDER.get(row["ext"], "placeholder\n"), encoding="utf-8")
def lane(receipt: dict, field: str) -> dict: v = receipt.get(field) return v if isinstance(v, dict) else {}
def lane_status(receipt: dict, field: str) -> str: return str(lane(receipt, field).get("status") or "missing")
def detect_hardcoded(payload: dict, receipt: dict) -> list[str]: blob = json.dumps(payload.get("coder_diagnostics", {}), default=str) + json.dumps( payload.get("coder_packet", {}), default=str ) hits = [m for m in HARDCODED_MARKERS if m in blob] rc = str(payload.get("reason_code") or "") if rc in HARDCODED_REASON_CODES: hits.append(f"reason_code:{rc}") return hits
def classify(row: dict, receipt: dict, trace_matches: bool, payload: dict) -> dict: verdict = str(receipt.get("final_verdict") or "") qwen = lane_status(receipt, "qwen_coder_status") det = lane(receipt, "deterministic_verifier_status") browser = lane(receipt, "browser_behavior_status") hermes_v = lane(receipt, "hermes_verifier_status") final_hash = str(receipt.get("final_coder_packet_hash") or "") recv_hash = str(receipt.get("coder_received_packet_hash") or "") protected = lane_status(receipt, "protected_path_check") diff = receipt.get("diff_summary") if isinstance(receipt.get("diff_summary"), dict) else {} changed = [str(x).replace("\\", "/") for x in (diff.get("changed_files") or [])] inside = (all(c.startswith(ALLOWED_ROOT_REL) for c in changed) if changed else None) has_fip4 = "fip4_qwen_coder_result" in receipt has_fip5 = "fip5_verifier_result" in receipt hardcoded = detect_hardcoded(payload, receipt)
facts = { "verdict": verdict, "qwen_coder_status": qwen, "deterministic_status": det.get("status"), "deterministic_passed": det.get("passed"), "browser_status": browser.get("status"), "browser_passed": browser.get("passed"), "hermes_verifier_status": hermes_v.get("status"), "hermes_verifier_verdict": hermes_v.get("verdict"), "final_coder_packet_hash": final_hash[:16], "coder_received_packet_hash": recv_hash[:16], "hash_match": bool(final_hash) and final_hash == recv_hash, "protected_path_status": protected, "changed_files": changed, "changed_inside_target_root": inside, "has_fip4_result": has_fip4, "has_fip5_result": has_fip5, "hardcoded_markers": hardcoded, "repair_attempt_count": receipt.get("repair_attempt_count"), "repair_max_attempts": receipt.get("repair_max_attempts"), "searxng_status": lane_status(receipt, "searxng_status"), "scout_status": lane_status(receipt, "scout_status"), }
if not trace_matches: return {"score_class": "trace_mismatch", "hard_fail": True, "facts": facts} if hardcoded: return {"score_class": "hardcoded_used", "hard_fail": True, "facts": facts} if protected == "blocked" and recv_hash == "" and qwen == "skipped" and not changed: return {"score_class": "expected_safety_block", "hard_fail": False, "facts": facts} if verdict.startswith("CONFIG-BLOCKED"): return {"score_class": "config_blocked", "hard_fail": False, "facts": facts} if verdict.startswith("GO:"): if not (verdict.startswith("GO: fip5") or verdict.startswith("GO: fip4")): return {"score_class": "preview_only_go", "hard_fail": True, "facts": facts} productive = ( qwen == "used" and bool(final_hash) and final_hash == recv_hash and det.get("status") == "used" and inside is True and protected != "blocked" and has_fip5 ) if not productive: return {"score_class": "productive_go_integrity_fail", "hard_fail": True, "facts": facts} warns = [] if facts["searxng_status"] == "failed": warns.append("searxng_failed") if facts["scout_status"] == "failed": warns.append("scout_failed") facts["lane_truth_warnings"] = warns return {"score_class": "lane_truth_warning" if warns else "productive_go", "hard_fail": False, "facts": facts} # NO-GO family if "browser_behavior_authority_blocks_pass" in verdict: return {"score_class": "verifier_blocked_browser", "hard_fail": False, "facts": facts} if "repair_attempts_exhausted" in verdict: return {"score_class": "repair_failure", "hard_fail": False, "facts": facts} if qwen in {"failed", "blocked"} or "output_contract" in verdict: return {"score_class": "coding_failure", "hard_fail": False, "facts": facts} if hermes_v.get("status") in {"blocked", "failed"} or "verifier_did_not_accept" in verdict: return {"score_class": "verifier_blocked", "hard_fail": False, "facts": facts} return {"score_class": "unexpected_no_go", "hard_fail": True, "facts": facts}
def run_row(row: dict) -> dict: ensure_target(row) body = { "task": f"Target file: {row['target']}\n\n{row['raw_prompt']}", "wants_implementation": True, "allowed_files": [row["target"]], "forbidden_files": FORBIDDEN_FILES, } rec = {"prompt_id": row["prompt_id"], "set_id": row["set_id"], "raw_prompt": row["raw_prompt"], "category": row["category"], "target": row["target"], "expected_score_class": row["expected_score_class"], "body": body, "posted_at": datetime.now(timezone.utc).isoformat()} t0 = time.time() try: status, payload = request_json("POST", "/v1/decisions/prompt-packet", body) except Exception as exc: # noqa: BLE001 rec.update({"post_status": "error", "error": f"{type(exc).__name__}: {exc}", "score_class": "config_blocked", "elapsed_s": round(time.time() - t0, 1)}) log(f"{row['prompt_id']}: POST error {rec['error']}") return rec elapsed = round(time.time() - t0, 1) receipt = payload.get("fip0_truth_receipt") or {} run_id = receipt.get("run_id") rec.update({"post_status": status, "run_id": run_id, "post_verdict": receipt.get("final_verdict"), "elapsed_s": elapsed}) if not run_id: rec.update({"score_class": "config_blocked", "error": "missing run_id in response"}) log(f"{row['prompt_id']}: no run_id, verdict={receipt.get('final_verdict')}") return rec # durable receipt + trace by run id try: _, rec_payload = request_json("GET", f"/v1/decisions/fip0-receipts/{run_id}", timeout=90) _, trace_payload = request_json("GET", f"/v1/decisions/fip0-receipts/{run_id}/trace", timeout=90) except Exception as exc: # noqa: BLE001 rec.update({"score_class": "config_blocked", "error": f"receipt/trace fetch: {exc}"}) return rec durable = rec_payload.get("receipt") or {} trace = trace_payload.get("operator_trace") or {} trace_verdict = (trace.get("verdict_trace") or {}).get("final_verdict") trace_matches = trace_verdict == durable.get("final_verdict") # persist receipt + trace copies (RECEIPTS / f"{row['prompt_id']}-{run_id}.json").write_text( json.dumps(durable, indent=2, sort_keys=True, default=str), encoding="utf-8") (TRACES / f"{row['prompt_id']}-{run_id}.json").write_text( json.dumps(trace, indent=2, sort_keys=True, default=str), encoding="utf-8") result = classify(row, durable, trace_matches, payload) rec.update({ "durable_verdict": durable.get("final_verdict"), "trace_verdict": trace_verdict, "trace_matches_receipt": trace_matches, "score_class": result["score_class"], "hard_fail": result["hard_fail"], "facts": result["facts"], "receipt_path": f"docs/evidence/source-proxy-claude-3x10-audit-20260615/receipts/{row['prompt_id']}-{run_id}.json", "trace_path": f"docs/evidence/source-proxy-claude-3x10-audit-20260615/traces/{row['prompt_id']}-{run_id}.json", }) f = result["facts"] log(f"{row['prompt_id']}: {result['score_class']} | verdict={f['verdict']} | qwen={f['qwen_coder_status']} " f"det={f['deterministic_passed']} browser={f['browser_passed']} hermesV={f['hermes_verifier_verdict']} " f"hashmatch={f['hash_match']} repair={f['repair_attempt_count']} {elapsed}s") return rec
def load_records() -> dict: p = EVID / "battery-raw.json" if p.exists(): try: return {r["prompt_id"]: r for r in json.loads(p.read_text())["records"]} except Exception: # noqa: BLE001 return {} return {}
def summarize(records: dict) -> dict: rows = list(records.values()) classes = {} for r in rows: classes[r.get("score_class", "?")] = classes.get(r.get("score_class", "?"), 0) + 1 return { "generated_at": datetime.now(timezone.utc).isoformat(), "total": len(rows), "by_score_class": classes, "productive_go": classes.get("productive_go", 0), "lane_truth_warning": classes.get("lane_truth_warning", 0), "verifier_blocked_browser": classes.get("verifier_blocked_browser", 0), "verifier_blocked": classes.get("verifier_blocked", 0), "coding_failure": classes.get("coding_failure", 0), "repair_failure": classes.get("repair_failure", 0), "config_blocked": classes.get("config_blocked", 0), "expected_safety_block": classes.get("expected_safety_block", 0), "trace_mismatch": classes.get("trace_mismatch", 0), "preview_only_go": classes.get("preview_only_go", 0), "hardcoded_used": classes.get("hardcoded_used", 0), "productive_go_integrity_fail": classes.get("productive_go_integrity_fail", 0), "unexpected_no_go": classes.get("unexpected_no_go", 0), "hard_fail_rows": [r["prompt_id"] for r in rows if r.get("hard_fail")], "matrix": [ { "prompt_id": r["prompt_id"], "set_id": r["set_id"], "category": r["category"], "raw_prompt": r["raw_prompt"], "target": r["target"], "expected_score_class": r.get("expected_score_class"), "score_class": r.get("score_class"), "run_id": r.get("run_id"), "durable_verdict": r.get("durable_verdict"), "trace_matches_receipt": r.get("trace_matches_receipt"), "elapsed_s": r.get("elapsed_s"), } for r in sorted(rows, key=lambda x: x["prompt_id"]) ], }
def main() -> None: ap = argparse.ArgumentParser() ap.add_argument("--set", default="1", help="1|2|3|all") ap.add_argument("--only", default="", help="single prompt_id") args = ap.parse_args() all_rows = matrix() (EVID / "battery-matrix.json").write_text( json.dumps({"generated_at": datetime.now(timezone.utc).isoformat(), "rows": all_rows}, indent=2, sort_keys=True), encoding="utf-8") if args.only: rows = [r for r in all_rows if r["prompt_id"] == args.only] elif args.set == "all": rows = all_rows else: rows = [r for r in all_rows if r["set_id"] == int(args.set)] records = load_records() log(f"START set={args.set} only={args.only or '-'} rows={len(rows)}") for row in rows: records[row["prompt_id"]] = run_row(row) (EVID / "battery-raw.json").write_text( json.dumps({"records": list(records.values())}, indent=2, sort_keys=True, default=str), encoding="utf-8") (EVID / "battery-results.json").write_text( json.dumps(summarize(records), indent=2, sort_keys=True, default=str), encoding="utf-8") s = summarize(records) log(f"DONE set={args.set}: {json.dumps(s['by_score_class'], sort_keys=True)}") print(json.dumps(s["by_score_class"], sort_keys=True))
if __name__ == "__main__": main()
